@dataclass(frozen=True)
class AssetCatalog:
    """Static Build 42 AnimSet and voice-catalog symbol index for cross-IR validation."""

    anim_states: frozenset[str]
    anim_variables: frozenset[str]
    voice_events: frozenset[str]


def sha256_json(value: Any) -> str:
    encoded = json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode(
        "utf-8"
    )
    return hashlib.sha256(encoded).hexdigest()


def scan_portability(value: Any, path: str) -> None:
    """Fail closed if portable IR text embeds engine-coupled or adopter-coupled symbols."""
    if isinstance(value, str):
        hit = _FORBIDDEN_PORTABILITY_RE.search(value)
        if hit:
            raise CompileError(
                f"Portable AI IR {path} contains forbidden engine/adopter symbol {hit.group(0)!r}"
            )
    elif isinstance(value, list):
        for idx, item in enumerate(value):
            scan_portability(item, f"{path}[{idx}]")
    elif isinstance(value, Mapping):
        for k, v in value.items():
            scan_portability(str(k), f"{path}.{k}")
            scan_portability(v, f"{path}.{k}")


def require_number(value: Any, label: str, lo: float, hi: float) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise CompileError(f"{label} must be a number (got {value!r})")
    num = float(value)
    if num < lo or num > hi:
        raise CompileError(f"{label}={num} outside allowed bounds [{lo}, {hi}]")
    return num


def require_int(value: Any, label: str, lo: int, hi: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise CompileError(f"{label} must be an integer (got {value!r})")
    if value < lo or value > hi:
        raise CompileError(f"{label}={value} outside allowed bounds [{lo}, {hi}]")
    return value


def require_identifier(value: Any, label: str) -> str:
    if not isinstance(value, str) or not IDENTIFIER_RE.match(value):
        raise CompileError(f"{label} must be a valid identifier (got {value!r})")
    return value


def _deep_merge_records(parent: Mapping[str, Any], child: Mapping[str, Any]) -> dict[str, Any]:
    merged: dict[str, Any] = copy.deepcopy(dict(parent))
    for key, value in child.items():
        if key in ("abstract", "parent"):
            continue
        if value is None:
            merged.pop(key, None)
        elif isinstance(value, Mapping) and isinstance(merged.get(key), Mapping):
            merged[key] = _deep_merge_records(merged[key], value)
        else:
            merged[key] = copy.deepcopy(value)
    return merged


def flatten_inheritance(
    entries: Iterable[Mapping[str, Any]],
    *,
    id_field: str = "id",
    source_label: str = "ir",
    max_depth: int = 8,
) -> list[dict[str, Any]]:
    """Flatten offline abstract/parent inheritance chains with cycle and depth guards."""
    by_id: dict[str, dict[str, Any]] = {}
    for idx, raw in enumerate(entries):
        if not isinstance(raw, Mapping):
            raise CompileError(f"{source_label}[{idx}]: entry must be an object")
        entry_id = raw.get(id_field)
        if not isinstance(entry_id, str) or not IDENTIFIER_RE.match(entry_id):
            raise CompileError(f"{source_label}[{idx}]: invalid {id_field} {entry_id!r}")
        if entry_id in by_id:
            raise CompileError(f"{source_label}: duplicate entry id {entry_id!r}")
        by_id[entry_id] = copy.deepcopy(dict(raw))

    resolved_cache: dict[str, dict[str, Any]] = {}

    def resolve_one(entry_id: str, stack: tuple[str, ...]) -> dict[str, Any]:
        if entry_id in resolved_cache:
            return resolved_cache[entry_id]
        if len(stack) >= max_depth:
            raise CompileError(
                f"{source_label}#{entry_id}: inheritance chain exceeds max depth {max_depth}"
            )
        raw = by_id[entry_id]
        parent_id = raw.get("parent")
        if parent_id is None:
            out = {k: copy.deepcopy(v) for k, v in raw.items() if k not in ("abstract", "parent")}
            resolved_cache[entry_id] = out
            return out
        if not isinstance(parent_id, str) or not parent_id:
            raise CompileError(f"{source_label}#{entry_id}: parent must be a non-empty string")
        if parent_id in stack or parent_id == entry_id:
            cycle = " -> ".join([*stack, entry_id, parent_id])
            raise CompileError(f"{source_label}: inheritance cycle detected: {cycle}")
        if parent_id not in by_id:
            raise CompileError(
                f"{source_label}#{entry_id}: missing parent template {parent_id!r}"
            )
        parent_resolved = resolve_one(parent_id, (*stack, entry_id))
        merged = _deep_merge_records(parent_resolved, raw)
        resolved_cache[entry_id] = merged
        return merged

    concrete: list[dict[str, Any]] = []
    for entry_id in sorted(by_id):
        raw = by_id[entry_id]
        flattened = resolve_one(entry_id, ())
        if bool(raw.get("abstract", False)):
            continue
        concrete.append(flattened)
    return concrete


def _unescape_pointer_segment(seg: str) -> str:
    return seg.replace("~1", "/").replace("~0", "~")


def _resolve_pointer(doc: Any, pointer: str, *, label: str) -> tuple[Any, str | int]:
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise CompileError(f"{label}: JSON Patch path must start with '/' (got {pointer!r})")
    parts = [_unescape_pointer_segment(p) for p in pointer.split("/")[1:]]
    if not parts:
        raise CompileError(f"{label}: root pointer '/' is not supported for overlay mutation")
    cur = doc
    for seg in parts[:-1]:
        if isinstance(cur, list):
            if not seg.isdigit():
                raise CompileError(f"{label}: list index must be numeric at {pointer!r} (got {seg!r})")
            idx = int(seg)
            if idx < 0 or idx >= len(cur):
                raise CompileError(f"{label}: list index {idx} out of range at {pointer!r}")
            cur = cur[idx]
        elif isinstance(cur, dict):
            if seg not in cur:
                raise CompileError(f"{label}: missing object key {seg!r} in pointer {pointer!r}")
            cur = cur[seg]
        else:
            raise CompileError(f"{label}: cannot traverse non-container at {pointer!r}")
    leaf = parts[-1]
    if isinstance(cur, list):
        if leaf == "-":
            return cur, "-"
        if not leaf.isdigit():
            raise CompileError(f"{label}: list index must be numeric at {pointer!r} (got {leaf!r})")
        return cur, int(leaf)
    if isinstance(cur, dict):
        return cur, leaf
    raise CompileError(f"{label}: target parent is not a container at {pointer!r}")


def apply_json_patch_overlays(
    document: Mapping[str, Any],
    patch_entries: Iterable[Mapping[str, Any]],
    *,
    label: str = "overlay",
) -> dict[str, Any]:
    """Apply an RFC 6902 JSON Patch sequence (add/replace/remove/test) to a document."""
    doc = copy.deepcopy(dict(document))
    for idx, op_entry in enumerate(patch_entries):
        if not isinstance(op_entry, Mapping):
            raise CompileError(f"{label}[{idx}]: patch operation must be an object")
        op = op_entry.get("op")
        path = op_entry.get("path")
        step_label = f"{label}[{idx}]({op})"
        if op not in ("add", "replace", "remove", "test"):
            raise CompileError(f"{step_label}: unsupported JSON Patch op {op!r}")
        parent, leaf = _resolve_pointer(doc, path, label=step_label)
        if op == "add":
            if "value" not in op_entry:
                raise CompileError(f"{step_label}: 'add' requires 'value'")
            val = copy.deepcopy(op_entry["value"])
            if isinstance(parent, list):
                if leaf == "-":
                    parent.append(val)
                elif isinstance(leaf, int) and 0 <= leaf <= len(parent):
                    parent.insert(leaf, val)
                else:
                    raise CompileError(f"{step_label}: index {leaf!r} out of range for add")
            else:
                parent[str(leaf)] = val
        elif op == "replace":
            if "value" not in op_entry:
                raise CompileError(f"{step_label}: 'replace' requires 'value'")
            val = copy.deepcopy(op_entry["value"])
            if isinstance(parent, list):
                if not isinstance(leaf, int) or leaf < 0 or leaf >= len(parent):
                    raise CompileError(f"{step_label}: index {leaf!r} out of range for replace")
                parent[leaf] = val
            else:
                if str(leaf) not in parent:
                    raise CompileError(f"{step_label}: missing target key {leaf!r} for replace")
                parent[str(leaf)] = val
        elif op == "remove":
            if isinstance(parent, list):
                if not isinstance(leaf, int) or leaf < 0 or leaf >= len(parent):
                    raise CompileError(f"{step_label}: index {leaf!r} out of range for remove")
                parent.pop(leaf)
            else:
                if str(leaf) not in parent:
                    raise CompileError(f"{step_label}: missing target key {leaf!r} for remove")
                parent.pop(str(leaf))
        elif op == "test":
            if "value" not in op_entry:
                raise CompileError(f"{step_label}: 'test' requires 'value'")
            expected = op_entry["value"]
            if isinstance(parent, list):
                if not isinstance(leaf, int) or leaf < 0 or leaf >= len(parent):
                    raise CompileError(f"{step_label}: index {leaf!r} out of range for test")
                actual = parent[leaf]
            else:
                if str(leaf) not in parent:
                    raise CompileError(f"{step_label}: missing target key {leaf!r} for test")
                actual = parent[str(leaf)]
            if actual != expected:
                raise CompileError(
                    f"{step_label}: JSON Patch test failed at {path!r}: expected {expected!r}, got {actual!r}"
                )
    return doc


def apply_shard_overlays(
    shard_doc: Mapping[str, Any],
    *,
    shard_rel: str,
    overlay_docs: Iterable[tuple[str, Mapping[str, Any]]],
) -> dict[str, Any]:
    """Apply matching overlay patch documents whose 'targetShard' equals shard_rel."""
    current = copy.deepcopy(dict(shard_doc))
    for overlay_rel, overlay_doc in overlay_docs:
        target = overlay_doc.get("targetShard")
        if target is not None and str(target) != shard_rel:
            continue
        ops = overlay_doc.get("operations")
        if ops is None:
            ops = overlay_doc.get("patch")
        if not isinstance(ops, list):
            raise CompileError(f"{overlay_rel}: overlay must declare an 'operations' list")
        current = apply_json_patch_overlays(current, ops, label=overlay_rel)
    return current


def load_package_overlays(
    package_root: Path,
    declared_overlays: Any,
) -> list[tuple[str, dict[str, Any]]]:
    """Load declared JSON Patch overlay manifests in deterministic order."""
    if declared_overlays is None:
        return []
    if not isinstance(declared_overlays, list):
        raise CompileError(f"{package_root}/package.json: overlays must be a list")
    loaded: list[tuple[str, dict[str, Any]]] = []
    for rel in declared_overlays:
        if not isinstance(rel, str) or not rel.strip():
            raise CompileError(f"{package_root}/package.json: invalid overlay path {rel!r}")
        overlay_path = (package_root / rel).resolve()
        if not overlay_path.is_file():
            raise CompileError(f"{package_root}/package.json: overlay file not found: {rel}")
        doc = json.loads(overlay_path.read_text(encoding="utf-8"))
        if not isinstance(doc, Mapping):
            raise CompileError(f"{rel}: overlay file must contain a JSON object")
        scan_portability(doc, rel)
        loaded.append((rel, dict(doc)))
    return loaded


def load_b42_asset_catalog(
    hoomans_repo: Path | None = None,
    *,
    extra_anim_vars: Iterable[str] = (),
    extra_voice_keys: Iterable[str] = (),
) -> AssetCatalog:
    """Build static Build 42 AnimSet and PNC.NPCVoice.Catalog validation index."""
    anim_states: set[str] = set()
    anim_variables: set[str] = set(_FALLBACK_ANIM_VARIABLES) | {str(v) for v in extra_anim_vars}
    voice_events: set[str] = set(_FALLBACK_VOICE_EVENTS) | {str(v) for v in extra_voice_keys}

    if hoomans_repo is not None:
        mod_root = Path(hoomans_repo).expanduser().resolve() / "Contents/mods/ProjectHoomans"
        anim_root = mod_root / "common/media/AnimSets/zombie"
        if anim_root.is_dir():
            for xml_path in sorted(anim_root.rglob("*.xml")):
                rel_parts = xml_path.relative_to(anim_root).parts
                if len(rel_parts) >= 2:
                    anim_states.add(rel_parts[0])
                try:
                    tree = ET.parse(xml_path)
                except ET.ParseError as exc:
                    raise CompileError(f"Invalid AnimSet XML {xml_path}: {exc}") from exc
                root = tree.getroot()
                for cond in root.findall(".//m_Conditions"):
                    name_el = cond.find("m_Name")
                    if name_el is not None and name_el.text and name_el.text.strip():
                        anim_variables.add(name_el.text.strip())

        for lua_path in sorted(
            mod_root.glob("*/media/lua/shared/PNC/Core/Visuals/PNC_Animation/*.lua")
        ):
            text = lua_path.read_text(encoding="utf-8", errors="replace")
            for match in _SET_VARIABLE_RE.finditer(text):
                anim_variables.add(match.group(1))

        for voice_lua in sorted(mod_root.glob("*/media/lua/client/PNC/Audio/PNC_NPCVoiceCatalog.lua")):
            for line in voice_lua.read_text(encoding="utf-8", errors="replace").splitlines():
                match = _VOICE_EVENT_RE.match(line)
                if match:
                    voice_events.add(match.group(1))

    return AssetCatalog(
        anim_states=frozenset(anim_states),
        anim_variables=frozenset(anim_variables),
        voice_events=frozenset(voice_events),
    )
